import Foundation

/// Why a pasteboard snapshot must not be recorded.
public enum SkipReason: String, Sendable, Equatable, Codable {
    /// org.nspasteboard.ConcealedType (passwords).
    case concealed
    /// org.nspasteboard.TransientType.
    case transient
    /// org.nspasteboard.AutoGeneratedType.
    case autoGenerated
    /// A legacy/vendor "do not record" marker (e.g. com.agilebits.onepassword).
    case ignoredType
    /// Nothing usable on the pasteboard.
    case empty
    /// Only types ClipSync does not understand.
    case unsupported
}

/// Result of classifying a pasteboard snapshot.
public enum ClipClassification: Sendable, Equatable {
    case skip(SkipReason)
    case kind(ClipKind)

    /// The kind, or nil when skipped.
    public var kind: ClipKind? {
        switch self {
        case .kind(let kind): return kind
        case .skip: return nil
        }
    }

    public var isSkipped: Bool {
        return kind == nil
    }
}

/// Decides the `ClipKind` of a pasteboard snapshot from its type list and string content.
/// Pure logic, platform-independent.
public enum PasteboardTypeClassifier {
    /// The skip reason if any marker type is present (concealed checked first).
    public static func markerSkipReason(for types: [String]) -> SkipReason? {
        let normalized = Set(TypeNormalizer.normalize(types))
        if normalized.contains(ClipUTI.concealed) { return .concealed }
        if normalized.contains(ClipUTI.transient) { return .transient }
        if normalized.contains(ClipUTI.autoGenerated) { return .autoGenerated }
        if !normalized.isDisjoint(with: ClipUTI.legacySkipTypes) { return .ignoredType }
        return nil
    }

    /// Classification rules, in order:
    /// 1. any marker type → skip
    /// 2. file URL → .file
    /// 3. with visible text: URL type + link text → .link; rich type → .richText;
    ///    link text → .link; color text → .color; image type → .image; else → .text
    /// 4. without text: URL type → .link; PDF → .pdf; image → .image; rich → .richText;
    ///    color type → .color; no types → skip(.empty); else skip(.unsupported)
    public static func classify(types rawTypes: [String], string: String?) -> ClipClassification {
        if let reason = markerSkipReason(for: rawTypes) {
            return .skip(reason)
        }
        let types = TypeNormalizer.normalize(rawTypes)
        let typeSet = Set(types)
        let text = (string ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        let hasText = !text.isEmpty
        let hasRich = types.contains { ClipUTI.isRichText($0) }
        let hasImage = types.contains { ClipUTI.isImage($0) }
        let hasPDF = typeSet.contains(ClipUTI.pdf)
        let hasURLType = typeSet.contains(ClipUTI.url)

        if typeSet.contains(ClipUTI.fileURL) {
            return .kind(.file)
        }
        if hasText {
            if hasURLType && isLink(text) { return .kind(.link) }
            if hasRich { return .kind(.richText) }
            if isLink(text) { return .kind(.link) }
            if isColor(text) { return .kind(.color) }
            if hasImage { return .kind(.image) }
            return .kind(.text)
        }
        if hasURLType { return .kind(.link) }
        if hasPDF { return .kind(.pdf) }
        if hasImage { return .kind(.image) }
        if hasRich { return .kind(.richText) }
        if typeSet.contains(ClipUTI.color) { return .kind(.color) }
        if types.isEmpty { return .skip(.empty) }
        return .skip(.unsupported)
    }

    /// A single token that parses as an http(s)/ftp(s) URL with a host, or a mailto: address.
    public static func isLink(_ string: String) -> Bool {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty, trimmed.count <= 4096 else { return false }
        guard trimmed.rangeOfCharacter(from: .whitespacesAndNewlines) == nil else { return false }
        guard let url = URL(string: trimmed), let scheme = url.scheme?.lowercased() else { return false }
        switch scheme {
        case "http", "https", "ftp", "ftps":
            guard let host = url.host, !host.isEmpty else { return false }
            return true
        case "mailto":
            return trimmed.contains("@")
        default:
            return false
        }
    }

    /// "#RGB", "#RRGGBB", "#RRGGBBAA", "rgb(...)", "rgba(...)".
    public static func isColor(_ string: String) -> Bool {
        return ColorParser.isColor(string)
    }
}
